const CreateFeatureNamingPatternSchemaSchema = z
  .object({
    pattern: z
      .string()
      .nullable()
      .openapi({
        description:
          'A JavaScript regular expression pattern, without the start and end delimiters. Optional flags are not allowed.',
        example: '^[A-Za-z]+\\.[A-Za-z]+\\.[A-Za-z0-9-]+$',
      }),
    example: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'An example of a feature name that matches the pattern. Must itself match the pattern supplied.',
        example: 'dx.feature.1-135',
      }),
    description: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'A description of the pattern in a human-readable format. Will be shown to users when they create a new feature flag.',
        example:
          '<project>.<featureName>.<ticket>\n\nThe flag name should contain the project name, the feature name, and the ticket number, each separated by a dot.',
      }),
  })
  .openapi({ description: 'Create a feature naming pattern', required: ['pattern'] })
  .openapi('CreateFeatureNamingPatternSchema')

