type PlaygroundFeatureSchemaType = {
  name: string
  projectId: string
  strategies: {
    result: boolean | 'unknown'
    data: z.infer<typeof PlaygroundStrategySchemaSchema>[]
  }
  hasUnsatisfiedDependency?: boolean
  isEnabledInCurrentEnvironment: boolean
  isEnabled: boolean
  variant: {
    name: string
    enabled: boolean
    payload?: { type: string; value: string }
    feature_enabled?: boolean
    featureEnabled?: boolean
  } | null
  variants: z.infer<typeof VariantSchemaSchema>[]
}

const PlaygroundFeatureSchemaSchema: z.ZodType<PlaygroundFeatureSchemaType> = z
  .strictObject({
    name: z.string().openapi({ example: 'my-feature', description: "The feature's name." }),
    projectId: z
      .string()
      .openapi({
        example: 'my-project',
        description: 'The ID of the project that contains this feature.',
      }),
    strategies: z
      .strictObject({
        result: z
          .union([z.boolean(), z.literal('unknown')])
          .openapi({
            description:
              "The cumulative results of all the feature's strategies. Can be `true`,\n                                  `false`, or `unknown`.\n                                  This property will only be `unknown`\n                                  if one or more of the strategies can't be fully evaluated and the rest of the strategies\n                                  all resolve to `false`.",
          }),
        data: z
          .array(PlaygroundStrategySchemaSchema)
          .openapi({ description: 'The strategies that apply to this feature.' }),
      })
      .openapi({
        required: ['result', 'data'],
        description: "The feature's applicable strategies and cumulative results of the strategies",
      }),
    hasUnsatisfiedDependency: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Whether the feature has a parent dependency that is not satisfied',
      }),
    isEnabledInCurrentEnvironment: z
      .boolean()
      .openapi({
        description:
          'Whether the feature is active and would be evaluated in the provided environment in a normal SDK context.',
      }),
    isEnabled: z
      .boolean()
      .openapi({
        description:
          "Whether this feature is enabled or not in the current environment.\n                          If a feature can't be fully evaluated (that is, `strategies.result` is `unknown`),\n                          this will be `false` to align with how client SDKs treat unresolved feature states.",
        example: true,
      }),
    variant: z
      .strictObject({
        name: z
          .string()
          .openapi({
            description:
              "The variant's name. If there is no variant or if the flag is disabled, this will be `disabled`",
            example: 'red-variant',
          }),
        enabled: z
          .boolean()
          .openapi({
            description:
              "Whether the variant is enabled or not. If the feature is disabled or if it doesn't have variants, this property will be `false`",
          }),
        payload: z
          .strictObject({
            type: z.string().openapi({ description: 'The format of the payload.' }),
            value: z
              .string()
              .openapi({
                description: 'The payload value stringified.',
                example: '{"property": "value"}',
              }),
          })
          .exactOptional()
          .openapi({
            required: ['type', 'value'],
            description: 'An optional payload attached to the variant.',
          }),
        feature_enabled: z
          .boolean()
          .exactOptional()
          .openapi({ description: 'Use `featureEnabled` instead.', example: true }),
        featureEnabled: z
          .boolean()
          .exactOptional()
          .openapi({
            deprecated: true,
            description: 'Whether the feature is enabled or not.',
            example: true,
          }),
      })
      .nullable()
      .openapi({
        description:
          "The feature variant you receive based on the provided context or the _disabled\n                          variant_. If a feature is disabled or doesn't have any\n                          variants, you would get the _disabled variant_.\n                          Otherwise, you'll get one of thefeature's defined variants.",
        required: ['name', 'enabled'],
        example: { name: 'green', enabled: true },
      }),
    variants: z.array(VariantSchemaSchema).openapi({ description: 'The feature variants.' }),
  })
  .openapi({
    description: 'A simplified feature flag model intended for the Unleash playground.',
    required: [
      'name',
      'projectId',
      'isEnabled',
      'isEnabledInCurrentEnvironment',
      'variant',
      'variants',
      'strategies',
    ],
  })
  .openapi('PlaygroundFeatureSchema')

